588.         let end_frame_number: usize = start_frame_number + region.size() / mem::FRAME_SIZE - 1;
589. 
590.         // Check that all frames in the range are covered by the bitmap and free,
591.         // then book them. Uncovered frames indicate a memory layout bug.
592.         //
593.         // The coverage check runs unconditionally — including optimized builds —
594.         // because out-of-bounds indices must be rejected before attempting to set them.
595.         // This loop runs only at boot when booking memory regions, so the overhead is negligible.
596.         #[cfg_attr(verus_keep_ghost, verus_spec(invariant false))]
597.         for index in start_frame_number..=end_frame_number {
598.             if index >= self.bitmap.number_of_bits() {
599.                 let uncovered_addr: usize = index * mem::FRAME_SIZE;
600.                 let reason: &str = "frame index not covered by the bitmap";
601.                 #[cfg(not(verus_keep_ghost))]
602.                 error!("{} (frame={:#010x}, region={:?})", reason, uncovered_addr, region);
