610.                     let region_end: usize = region_start.saturating_add(region.size());
611.                     let reason: &str = "frame is already allocated";
612.                     #[cfg(not(verus_keep_ghost))]
613.                     error!(
614.                         "{} (frame={:#010x}, region_start={:#010x}, region_end={:#010x})",
615.                         reason, conflicting_addr, region_start, region_end
616.                     );
617.                     return Err(Error::new(ErrorCode::OutOfMemory, reason));
618.                 },
619.                 Err(err) => return Err(err),
620.             }
621.         }
622. 
623.         // Book all frames in the range.
624.         #[cfg_attr(verus_keep_ghost, verus_spec(invariant false))]
625.         for index in start_frame_number..=end_frame_number {
626.             if let Err(error) = self.bitmap.set(index) {
627.                 #[cfg(not(verus_keep_ghost))]
628.                 error!("{error:?} (region={region:?})");
