         ensures
             self.inv(),
             match result {
                 Ok(count) => {
                     &&& self@.allocated_frames.contains(frame@)
                     &&& self@.refcounts.contains_key(frame@)
                     &&& count as int == self@.refcounts[frame@]
                 },
                 Err(_) => {
                     !self@.allocated_frames.contains(frame@)
                 }
