     ///
     #[verus_spec(ret =>
         requires
             self.inv(),
             phys_addr.inv(),
         ensures
             self.inv(),
             ret <==> (
                 self@.allocated_frames.contains(phys_addr@)
                 || self@.free_frames.contains(phys_addr@)
