        vstd::set_lib::lemma_int_range(0, num_bits);
        let free_range: Set<int> = vstd::set_lib::set_int_range(p, p + n);
        vstd::set_lib::lemma_int_range(p, p + n);
        let available_range: Set<int> = full_range.difference(free_range);

